//! Files generated by tests and committed: the test fails when the
//! committed file differs. Rerun `cargo test` with
//! BIOPASS_UPDATE_GENERATED=1 to rewrite them, then commit.

use std::fs;
use std::path::Path;

/// Fails when the committed file at `relative` (to the repository root)
/// differs from `generated`. With BIOPASS_UPDATE_GENERATED set it writes the
/// file instead.
pub fn check(relative: &str, generated: &str) {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .join(relative);
    if std::env::var_os("BIOPASS_UPDATE_GENERATED").is_some() {
        fs::write(&path, generated).unwrap();
        return;
    }
    let committed = fs::read_to_string(&path).unwrap_or_default();
    assert!(
        committed == generated,
        "{relative} is out of date; run \
         `BIOPASS_UPDATE_GENERATED=1 cargo test` in app/src-tauri and commit it"
    );
}
